1	"use strict";
2	
3	const createPetGeometryMain = require("./pet-geometry-main");
4	const {
5	  computeLooseClamp,
6	  getDisplayInsets,
7	  findMatchingDisplay,
8	  isPointInAnyWorkArea,
9	  SYNTHETIC_WORK_AREA,
10	} = require("./work-area");
11	const {
12	  getThemeMarginBox,
13	  computeStableVisibleContentMargins,
14	  getLooseDragMargins,
15	  getRestClampMargins,
16	} = require("./visible-margins");
17	const {
18	  createDragSnapshot,
19	  computeAnchoredDragBounds,
20	  computeFinalDragBounds: computeFinalDragBoundsRaw,
21	  needsFinalClampAdjustment: needsFinalClampAdjustmentRaw,
22	  materializeVirtualBounds: materializeVirtualBoundsRaw,
23	} = require("./drag-position");
24	
25	const noop = () => {};
26	
27	function isLiveWindow(win) {
28	  return !!(win && typeof win.isDestroyed === "function" && !win.isDestroyed());
29	}
30	
31	function createPetWindowRuntime(options = {}) {
32	  const screen = options.screen || {};
33	  const isWin = !!options.isWin;
34	  const isMac = !!options.isMac;
35	  const isLinux = !!options.isLinux;
36	  const linuxWindowType = options.linuxWindowType;
37	  const topmostLevel = options.topmostLevel;
38	  const getRenderWindow = options.getRenderWindow || (() => null);
39	  const getHitWindow = options.getHitWindow || (() => null);
40	  const getSettingsWindow = options.getSettingsWindow || (() => null);
41	  const getPrimaryWorkAreaSafe = options.getPrimaryWorkAreaSafe || (() => null);
42	  const getNearestWorkArea = options.getNearestWorkArea || (() => getPrimaryWorkAreaSafe() || SYNTHETIC_WORK_AREA);
43	  const getActiveTheme = options.getActiveTheme || (() => null);
44	  const getCurrentState = options.getCurrentState || (() => null);
45	  const getCurrentSvg = options.getCurrentSvg || (() => null);
46	  const getCurrentHitBox = options.getCurrentHitBox || (() => null);
47	  const getMiniMode = options.getMiniMode || (() => false);
48	  const getMiniTransitioning = options.getMiniTransitioning || (() => false);
49	  const getMiniContainedSeam = options.getMiniContainedSeam || (() => null);
50	  const getMiniPeekOffset = options.getMiniPeekOffset || (() => 0);
51	  const getCurrentPixelSize = options.getCurrentPixelSize || (() => null);
52	  const getEffectiveCurrentPixelSize = options.getEffectiveCurrentPixelSize || getCurrentPixelSize;
53	  const getKeepSizeAcrossDisplays = options.getKeepSizeAcrossDisplays || (() => false);
54	  const getAllowEdgePinning = options.getAllowEdgePinning || (() => false);
55	  const isProportionalMode = options.isProportionalMode || (() => false);
56	  const sendToRenderer = options.sendToRenderer || noop;
57	  const keepOutOfTaskbar = options.keepOutOfTaskbar || noop;
58	  const repositionSessionHud = options.repositionSessionHud || noop;
59	  const repositionAnchoredSurfaces = options.repositionAnchoredSurfaces || noop;
60	  const repositionFloatingBubbles = options.repositionFloatingBubbles || noop;
61	  const showFloatingSurfacesForPet = options.showFloatingSurfacesForPet || noop;
62	  const hideFloatingSurfacesForPet = options.hideFloatingSurfacesForPet || noop;
63	  const syncSessionHudVisibilityAndBubbles = options.syncSessionHudVisibilityAndBubbles || noop;
64	  const syncPermissionShortcuts = options.syncPermissionShortcuts || noop;
65	  const buildTrayMenu = options.buildTrayMenu || noop;
66	  const buildContextMenu = options.buildContextMenu || noop;
67	  const reapplyMacVisibility = options.reapplyMacVisibility || noop;
68	  const reassertWinTopmost = options.reassertWinTopmost || noop;
69	  const scheduleHwndRecovery = options.scheduleHwndRecovery || noop;
70	  const isNearWorkAreaEdge = options.isNearWorkAreaEdge || (() => false);
71	  const flushRuntimeStateToPrefs = options.flushRuntimeStateToPrefs || noop;
72	  const handleMiniDisplayChange = options.handleMiniDisplayChange || noop;
73	  const exitMiniMode = options.exitMiniMode || noop;
74	
75	  const petGeometryMain = createPetGeometryMain({
76	    getActiveTheme,
77	    getCurrentState,
78	    getCurrentSvg,
79	    getCurrentHitBox,
80	    getMiniMode,
81	    getMiniPeekOffset,
82	  });
83	
84	  let viewportOffsetY = 0;
85	  let petHidden = false;
86	  let dragLocked = false;
87	  let dragSnapshot = null;
88	  let hitShapeWidth = 0;
89	  let hitShapeHeight = 0;
90	  let settingsSizePreviewSyncFrozen = false;
91	  const themeMarginEnvelopeCache = new Map();
92	
93	  function getPrimaryWorkAreaFallback() {
94	    return getPrimaryWorkAreaSafe() || SYNTHETIC_WORK_AREA;
95	  }
96	
97	  function getAllDisplays() {
98	    return typeof screen.getAllDisplays === "function" ? screen.getAllDisplays() : [];
99	  }
100	
101	  function getCursorScreenPoint() {
102	    return typeof screen.getCursorScreenPoint === "function"
103	      ? screen.getCursorScreenPoint()
104	      : null;
105	  }
106	
107	  function getNearestDisplayBottomInset(cx, cy) {
108	    const point = { x: Math.round(cx), y: Math.round(cy) };
109	    let display = null;
110	    try {
111	      if (typeof screen.getDisplayNearestPoint === "function") {
112	        display = screen.getDisplayNearestPoint(point);
113	      }
114	    } catch {}
115	    if (!display || !display.bounds || !display.workArea) {
116	      try {
117	        if (typeof screen.getPrimaryDisplay === "function") display = screen.getPrimaryDisplay();
118	      } catch {}
119	    }
120	    return getDisplayInsets(display).bottom;
121	  }
122	
123	  function setViewportOffsetY(offsetY) {
124	    const next = Number.isFinite(offsetY) ? Math.max(0, Math.round(offsetY)) : 0;
125	    if (next === viewportOffsetY) return;
126	    viewportOffsetY = next;
127	    sendToRenderer("viewport-offset", viewportOffsetY);
128	  }
129	
130	  function getViewportOffsetY() {
131	    return viewportOffsetY;
132	  }
133	
134	  function getPetWindowBounds() {
135	    const win = getRenderWindow();
136	    if (!isLiveWindow(win)) return null;
137	    const bounds = win.getBounds();
138	    return {
139	      x: bounds.x,
140	      y: bounds.y - viewportOffsetY,
141	      width: bounds.width,
142	      height: bounds.height,
143	    };
144	  }
145	
146	  function materializeVirtualBounds(bounds, workArea) {
147	    const resolvedWorkArea = workArea || (
148	      bounds
149	        ? getNearestWorkArea(bounds.x + bounds.width / 2, bounds.y + bounds.height / 2)
150	        : null
151	    );
152	    return materializeVirtualBoundsRaw(bounds, resolvedWorkArea);
153	  }
154	
155	  function applyPetWindowBounds(bounds) {
156	    const win = getRenderWindow();
157	    if (!isLiveWindow(win) || !bounds) return null;
158	    const materialized = materializeVirtualBounds(bounds);
159	    if (!materialized) return null;
160	    win.setBounds(materialized.bounds);
161	    setViewportOffsetY(materialized.viewportOffsetY);
162	    repositionSessionHud();
163	    return materialized.bounds;
164	  }
165	
166	  function applyPetWindowPosition(x, y) {
167	    const bounds = getPetWindowBounds();
168	    if (!bounds) return null;
169	    return applyPetWindowBounds({ ...bounds, x, y });
170	  }
171	
172	  function isPetHidden() {
173	    return petHidden;
174	  }
175	
176	  function showPetWindows() {
177	    const win = getRenderWindow();
178	    if (isLiveWindow(win)) {
179	      win.showInactive();
180	      keepOutOfTaskbar(win);
181	    }
182	    const hitWin = getHitWindow();
183	    if (isLiveWindow(hitWin)) {
184	      hitWin.showInactive();
185	      keepOutOfTaskbar(hitWin);
186	    }
187	  }
188	
189	  function hidePetWindows() {
190	    const win = getRenderWindow();
191	    if (isLiveWindow(win)) win.hide();
192	    const hitWin = getHitWindow();
193	    if (isLiveWindow(hitWin)) hitWin.hide();
194	  }
195	
196	  function togglePetVisibility() {
197	    const win = getRenderWindow();
198	    if (!isLiveWindow(win)) return;
199	    if (getMiniTransitioning()) return;
200	    if (petHidden) {
201	      showPetWindows();
202	      showFloatingSurfacesForPet();
203	      reapplyMacVisibility();
204	      petHidden = false;
205	    } else {
206	      hidePetWindows();
207	      hideFloatingSurfacesForPet();
208	      petHidden = true;
209	    }
210	    syncSessionHudVisibilityAndBubbles();
211	    syncPermissionShortcuts();
212	    buildTrayMenu();
213	    buildContextMenu();
214	  }
215	
216	  function bringPetToPrimaryDisplay() {
217	    const win = getRenderWindow();
218	    if (!isLiveWindow(win)) return;
219	    if (getMiniMode() || getMiniTransitioning()) return;
220	
221	    const workArea = getPrimaryWorkAreaFallback();
222	    const size = getEffectiveCurrentPixelSize(workArea);
223	    const bounds = {
224	      x: Math.round(workArea.x + (workArea.width - size.width) / 2),
225	      y: Math.round(workArea.y + (workArea.height - size.height) / 2),
226	      width: size.width,
227	      height: size.height,
228	    };
229	
230	    applyPetWindowBounds(bounds);
231	    syncHitWin();
232	    repositionFloatingBubbles();
233	
234	    if (petHidden) {
235	      togglePetVisibility();
236	    } else {
237	      showPetWindows();
238	    }
239	
240	    reapplyMacVisibility();
241	    reassertWinTopmost();
242	    scheduleHwndRecovery();
243	    flushRuntimeStateToPrefs();
244	  }
245	
246	  function getObjRect(bounds) {
247	    return petGeometryMain.getObjRect(bounds);
248	  }
249	
250	  function getAssetPointerPayload(bounds, point) {
251	    return petGeometryMain.getAssetPointerPayload(bounds, point);
252	  }
253	
254	  function getHitRectScreen(bounds) {
255	    return clipHitRectToMiniSeam(petGeometryMain.getHitRectScreen(bounds));
256	  }
257	
258	  function getUpdateBubbleAnchorRect(bounds) {
259	    return petGeometryMain.getUpdateBubbleAnchorRect(bounds);
260	  }
261	
262	  function getSessionHudAnchorRect(bounds) {
263	    return petGeometryMain.getSessionHudAnchorRect(bounds);
264	  }
265	
266	  function getVisibleContentMargins(bounds) {
267	    const theme = getActiveTheme();
268	    if (!bounds || !theme) return { top: 0, bottom: 0 };
269	    const box = getThemeMarginBox(theme);
270	    if (!box) return { top: 0, bottom: 0 };
271	
272	    const cacheKey = [
273	      theme._id || "",
274	      theme._variantId || "",
275	      bounds.width,
276	      bounds.height,
277	      JSON.stringify(box),
278	    ].join("|");
279	    const cached = themeMarginEnvelopeCache.get(cacheKey);
280	    if (cached) return cached;
281	
282	    const margins = computeStableVisibleContentMargins(theme, bounds, { box });
283	    themeMarginEnvelopeCache.set(cacheKey, margins);
284	    return margins;
285	  }
286	
287	  function looseClampPetToDisplays(x, y, w, h) {
288	    const margins = getVisibleContentMargins({ x, y, width: w, height: h });
289	    const bottomInset = getNearestDisplayBottomInset(x + w / 2, y + h / 2);
290	    return computeLooseClamp(
291	      getAllDisplays(),
292	      getPrimaryWorkAreaSafe(),
293	      x,
294	      y,
295	      w,
296	      h,
297	      getLooseDragMargins({
298	        width: w,
299	        height: h,
300	        visibleMargins: margins,
301	        allowEdgePinning: getAllowEdgePinning(),
302	        bottomInset,
303	      })
304	    );
305	  }
306	
307	  function clampToScreenVisual(x, y, w, h, optionsArg = {}) {
308	    const margins = getVisibleContentMargins(
309	      { x, y, width: w, height: h },
310	      optionsArg
311	    );
312	    const nearest = getNearestWorkArea(x + w / 2, y + h / 2);
313	    const bottomInset = getNearestDisplayBottomInset(x + w / 2, y + h / 2);
314	    const mLeft = Math.round(w * 0.25);
315	    const mRight = Math.round(w * 0.25);
316	    const clampMargins = getRestClampMargins({
317	      height: h,
318	      visibleMargins: margins,
319	      allowEdgePinning: "allowEdgePinning" in optionsArg
320	        ? optionsArg.allowEdgePinning
321	        : getAllowEdgePinning(),
322	      bottomInset,
323	    });
324	    return {
325	      x: Math.max(nearest.x - mLeft, Math.min(x, nearest.x + nearest.width - w + mRight)),
326	      y: Math.max(
327	        nearest.y - clampMargins.top,
328	        Math.min(y, nearest.y + nearest.height - h + clampMargins.bottom)
329	      ),
330	    };
331	  }
332	
333	  function clampToScreen(x, y, w, h) {
334	    return clampToScreenVisual(x, y, w, h);
335	  }
336	
337	  function computeFinalDragBounds(bounds, size, clampPosition = clampToScreenVisual) {
338	    return computeFinalDragBoundsRaw(bounds, size, clampPosition);
339	  }
340	
341	  function needsFinalClampAdjustment(bounds, size, clampPosition = clampToScreenVisual) {
342	    return needsFinalClampAdjustmentRaw(bounds, size, clampPosition);
343	  }
344	
345	  // At an internal multi-monitor seam the render window is clip-pathed so its
346	  // seam-crossing half shows nothing — but the hit (input) window is a
347	  // transparent surface and would keep capturing clicks over the neighbouring
348	  // display. Clip the hit rect to the same seam so those clicks fall through.
349	  // The clamps keep the rect from inverting when the whole hit rect is past
350	  // the seam; the w<=0 guard in the callers then drops the degenerate result.
351	  function clipHitRectToMiniSeam(hit) {
352	    if (!hit) return hit;
353	    const seam = getMiniContainedSeam();
354	    if (!seam || !Number.isFinite(seam.boundary)) return hit;
355	    if (seam.edge === "right") {
356	      if (hit.right <= seam.boundary) return hit;
357	      return { ...hit, right: Math.max(hit.left, seam.boundary) };
358	    }
359	    if (hit.left >= seam.boundary) return hit;
360	    return { ...hit, left: Math.min(hit.right, seam.boundary) };
361	  }
362	
363	  function syncHitWin() {
364	    const hitWin = getHitWindow();
365	    const win = getRenderWindow();
366	    if (!isLiveWindow(hitWin) || !isLiveWindow(win)) return;
367	    // Keep the captured pointer stable while dragging. Repositioning the input
368	    // window mid-drag can break pointer capture on Windows.
369	    if (dragLocked) return;
370	    const bounds = getPetWindowBounds();
371	    const hit = getHitRectScreen(bounds);
372	    if (!hit) return;
373	    const x = Math.round(hit.left);
374	    const y = Math.round(hit.top);
375	    const w = Math.round(hit.right - hit.left);
376	    const h = Math.round(hit.bottom - hit.top);
377	    if (w <= 0 || h <= 0) return;
378	    hitWin.setBounds({ x, y, width: w, height: h });
379	    // Update shape if hitbox dimensions changed (e.g. after resize).
380	    if (w !== hitShapeWidth || h !== hitShapeHeight) {
381	      hitShapeWidth = w;
382	      hitShapeHeight = h;
383	      hitWin.setShape([{ x: 0, y: 0, width: w, height: h }]);
384	    }
385	    repositionSessionHud();
386	  }
387	
388	  function getInitialHitWindowBounds(renderBounds = getPetWindowBounds()) {
389	    const hit = getHitRectScreen(renderBounds);
390	    if (!hit) return null;
391	    return {
392	      x: Math.round(hit.left),
393	      y: Math.round(hit.top),
394	      width: Math.round(hit.right - hit.left),
395	      height: Math.round(hit.bottom - hit.top),
396	    };
397	  }
398	
399	  function createRenderWindow(optionsArg = {}) {
400	    const BrowserWindow = optionsArg.BrowserWindow;
401	    if (typeof BrowserWindow !== "function") {
402	      throw new Error("createRenderWindow requires BrowserWindow");
403	    }
404	    const isQuitting = typeof optionsArg.isQuitting === "function" ? optionsArg.isQuitting : () => false;
405	    const size = optionsArg.size;
406	    const initialWindowBounds = optionsArg.initialWindowBounds;
407	    const renderWin = new BrowserWindow({
408	      width: size.width,
409	      height: size.height,
410	      x: initialWindowBounds.x,
411	      y: initialWindowBounds.y,
412	      frame: false,
413	      transparent: true,
414	      alwaysOnTop: true,
415	      resizable: false,
416	      skipTaskbar: true,
417	      hasShadow: false,
418	      fullscreenable: false,
419	      enableLargerThanScreen: true,
420	      ...(isLinux ? { type: linuxWindowType } : {}),
421	      ...(isMac ? { type: "panel", roundedCorners: false } : {}),
422	      webPreferences: {
423	        preload: optionsArg.preloadPath,
424	        backgroundThrottling: false,
425	        additionalArguments: [
426	          "--theme-config=" + JSON.stringify(optionsArg.themeConfig),
427	        ],
428	      },
429	    });
430	
431	    if (typeof optionsArg.setRenderWindow === "function") {
432	      optionsArg.setRenderWindow(renderWin);
433	    }
434	    renderWin.setFocusable(false);
435	
436	    if (isLinux) {
437	      renderWin.on("close", (event) => {
438	        if (!isQuitting()) {
439	          event.preventDefault();
440	          if (!renderWin.isVisible()) {
441	            renderWin.showInactive();
442	            keepOutOfTaskbar(renderWin);
443	          }
444	        }
445	      });
446	      renderWin.on("unresponsive", () => {
447	        if (isQuitting()) return;
448	        console.warn("Clawd: renderer unresponsive — reloading");
449	        renderWin.webContents.reload();
450	      });
451	    }
452	
453	    if (isWin) renderWin.setAlwaysOnTop(true, topmostLevel);
454	    renderWin.loadFile(optionsArg.loadFilePath);
455	    applyPetWindowBounds(optionsArg.initialVirtualBounds);
456	    renderWin.showInactive();
457	    keepOutOfTaskbar(renderWin);
458	    reapplyMacVisibility();
459	
460	    if (isMac && typeof optionsArg.applyDockVisibility === "function") {
461	      setTimeout(() => {
462	        if (!isLiveWindow(renderWin)) return;
463	        optionsArg.applyDockVisibility();
464	      }, 0);
465	    }
466	
467	    return renderWin;
468	  }
469	
470	  function createHitWindow(optionsArg = {}) {
471	    const BrowserWindow = optionsArg.BrowserWindow;
472	    if (typeof BrowserWindow !== "function") {
473	      throw new Error("createHitWindow requires BrowserWindow");
474	    }
475	    const initialHitWindowBounds = getInitialHitWindowBounds();
476	    const hitWin = new BrowserWindow({
477	      width: initialHitWindowBounds.width,
478	      height: initialHitWindowBounds.height,
479	      x: initialHitWindowBounds.x,
480	      y: initialHitWindowBounds.y,
481	      frame: false,
482	      transparent: true,
483	      alwaysOnTop: true,
484	      resizable: false,
485	      skipTaskbar: true,
486	      hasShadow: false,
487	      fullscreenable: false,
488	      enableLargerThanScreen: true,
489	      ...(isLinux ? { type: linuxWindowType } : {}),
490	      ...(isMac ? { type: "panel", roundedCorners: false } : {}),
491	      // KEY EXPERIMENT: allow activation to avoid WS_EX_NOACTIVATE input
492	      // routing bugs. Linux keeps the old non-focusable behavior.
493	      focusable: !isLinux,
494	      webPreferences: {
495	        preload: optionsArg.preloadPath,
496	        backgroundThrottling: false,
497	        additionalArguments: [
498	          "--hit-theme-config=" + JSON.stringify(optionsArg.hitThemeConfig),
499	          "--hit-platform=" + process.platform,
500	        ],
501	      },
502	    });
503	    // setShape: native hit region, no per-pixel alpha dependency.
504	    // hitWin has no visual content, so clipping is irrelevant.
505	    hitWin.setShape([{ x: 0, y: 0, width: initialHitWindowBounds.width, height: initialHitWindowBounds.height }]);
506	    hitWin.setIgnoreMouseEvents(false); // PERMANENT: never toggle outside settings preview protection.
507	    if (isMac) hitWin.setFocusable(false);
508	    hitWin.showInactive();
509	    keepOutOfTaskbar(hitWin);
510	    if (isWin) hitWin.setAlwaysOnTop(true, topmostLevel);
511	    reapplyMacVisibility();
512	    hitWin.loadFile(optionsArg.loadFilePath);
513	    if (isWin && typeof optionsArg.guardAlwaysOnTop === "function") {
514	      optionsArg.guardAlwaysOnTop(hitWin);
515	    }
516	    if (typeof optionsArg.onDidFinishLoad === "function") {
517	      hitWin.webContents.on("did-finish-load", () => optionsArg.onDidFinishLoad(hitWin));
518	    }
519	    hitWin.webContents.on("render-process-gone", (_event, details) => {
520	      if (typeof optionsArg.onRenderProcessGone === "function") {
521	        optionsArg.onRenderProcessGone(details, hitWin);
522	        return;
523	      }
524	      hitWin.webContents.reload();
525	    });
526	    return hitWin;
527	  }
528	
529	  function setDragLocked(value) {
530	    dragLocked = !!value;
531	  }
532	
533	  function isDragLocked() {
534	    return dragLocked;
535	  }
536	
537	  function beginDragSnapshot() {
538	    const win = getRenderWindow();
539	    if (!isLiveWindow(win)) {
540	      dragSnapshot = null;
541	      return;
542	    }
543	    const bounds = getPetWindowBounds();
544	    if (!bounds) {
545	      dragSnapshot = null;
546	      return;
547	    }
548	    // When keepSizeAcrossDisplays is on, the pet may currently be sized from
549	    // a prior display. Snapshotting getCurrentPixelSize() here would snap it
550	    // to the current display's proportional size at drag start.
551	    const size = getKeepSizeAcrossDisplays()
552	      ? { width: bounds.width, height: bounds.height }
553	      : getCurrentPixelSize();
554	    dragSnapshot = createDragSnapshot(
555	      getCursorScreenPoint(),
556	      bounds,
557	      size
558	    );
559	  }
560	
561	  function clearDragSnapshot() {
562	    dragSnapshot = null;
563	  }
564	
565	  function moveWindowForDrag() {
566	    if (!dragLocked) return;
567	    if (getMiniMode() || getMiniTransitioning()) return;
568	    if (!isLiveWindow(getRenderWindow())) return;
569	    if (!dragSnapshot) return;
570	
571	    const bounds = computeAnchoredDragBounds(
572	      dragSnapshot,
573	      getCursorScreenPoint(),
574	      looseClampPetToDisplays
575	    );
576	    if (!bounds) return;
577	
578	    applyPetWindowBounds(bounds);
579	    if (isWin && isNearWorkAreaEdge(bounds)) reassertWinTopmost();
580	    syncHitWin();
581	    repositionAnchoredSurfaces();
582	  }
583	
584	  function hasStoredPositionThemeMismatch(prefs) {
585	    const theme = getActiveTheme();
586	    if (!prefs || !theme) return false;
587	    return prefs.positionThemeId !== theme._id
588	      || prefs.positionVariantId !== theme._variantId;
589	  }
590	
591	  function resolveStartupPlacement(prefs, size, optionsArg = {}) {
592	    const restoreMiniFromPrefs = optionsArg.restoreMiniFromPrefs || (() => null);
593	    let startBounds;
594	    if (prefs.miniMode) {
595	      startBounds = restoreMiniFromPrefs(prefs, size);
596	    } else if (prefs.positionSaved) {
597	      startBounds = { x: prefs.x, y: prefs.y, width: size.width, height: size.height };
598	    } else {
599	      const workArea = getPrimaryWorkAreaFallback();
600	      startBounds = {
601	        x: workArea.x + workArea.width - size.width - 20,
602	        y: workArea.y + workArea.height - size.height - 20,
603	        width: size.width,
604	        height: size.height,
605	      };
606	    }
607	
608	    const allDisplays = getAllDisplays();
609	    const savedDisplayStillAttached = !!findMatchingDisplay(
610	      prefs.positionDisplay,
611	      allDisplays
612	    );
613	    const savedCenterVisible = isPointInAnyWorkArea(
614	      startBounds.x + startBounds.width / 2,
615	      startBounds.y + startBounds.height / 2,
616	      allDisplays
617	    );
618	    const startupNeedsRegularize = prefs.positionSaved
